<?php if (!empty($_SESSION['bulk_report'])): $bulkReport=$_SESSION['bulk_report']; ?>
<section class="card spaced" aria-label="Resultado de carga masiva"><h2>Resultado de la última carga masiva</h2><p class="muted"><?= (int)$bulkReport['file_count'] ?> PDF recibidos · <?= (int)$bulkReport['saved'] ?> historias guardadas · <?= (int)$bulkReport['reused'] ?> ya registradas · <?= (int)$bulkReport['failed'] ?> con errores<?= !empty($bulkReport['blocked']) ? ' · ' . (int)$bulkReport['blocked'] . ' grupos sin guardar' : '' ?>.</p>
<?php if (!empty($bulkReport['unreadable'])): ?><div class="notice warn"><?= ui_icon('alert') ?><p><strong><?= (int)$bulkReport['unreadable'] === 1 ? '1 PDF no se pudo leer y no se cargó.' : (int)$bulkReport['unreadable'] . ' PDF no se pudieron leer y no se cargaron.' ?></strong> Los demás se guardaron. Abajo está el motivo de cada uno<?= array_filter($bulkReport['results'], fn($result) => !empty($result['missing'])) ? '; a los que solo les falta un dato, puedes escribirlo ahí mismo' : '' ?>. Si alguno era anexo de una atención que sí se guardó, esa historia quedó sin ese anexo: corrígelo y vuelve a subirlo junto con todos los PDF de esa atención.</p></div><?php endif ?>
<div class="table-wrap"><table class="responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Archivos</th><th scope="col" role="columnheader">Paciente / atención</th><th scope="col" role="columnheader">Resultado</th></tr></thead><tbody role="rowgroup">
<?php foreach($bulkReport['results'] as $result): ?><tr role="row"><td role="cell" data-label="Archivos" class="bulk-files"><?php foreach($result['previews'] ?? array_map(fn($file)=>['name'=>$file],$result['files']) as $preview): ?><div><?= ui_pdf_preview($preview, count($result['files']) === 1 && !empty($result['page']) ? (int)$result['page'] : null) ?></div><?php endforeach ?><?php if (!empty($result['page'])): ?><span class="pill stop bulk-page">Página <?= (int)$result['page'] ?></span><?php endif ?></td><td role="cell" data-label="Paciente / atención"><?= h($result['patient'] ?? $result['found']['full_name'] ?? 'No identificado') ?><small><?= h($result['document'] ?? $result['found']['document'] ?? '') ?></small><small><?= isset($result['date']) ? h(date('d/m/Y',strtotime($result['date']))) : '' ?></small></td><td role="cell" data-label="Resultado" class="bulk-result"><span class="pill <?= ['saved'=>'ok','reused'=>'info','error'=>'stop','blocked'=>'stop'][$result['status']] ?>"><?= h(['saved'=>'Guardada','reused'=>'Ya registrada','error'=>'No se cargó','blocked'=>'Sin guardar'][$result['status']]) ?></span><p><?= h($result['message']) ?></p><?php $completeRef = $result['previews'][0]['ref'] ?? ''; if (!empty($result['missing']) && $completeRef !== ''): $missing = $result['missing']; $fieldId = 'pdf-' . h($completeRef); ?>
<form method="post" action="?page=admin" class="bulk-complete"><?= csrf() ?><input type="hidden" name="action" value="pdf-complete"><input type="hidden" name="ref" value="<?= h($completeRef) ?>">
<p class="bulk-complete-title"><?= ui_icon('file', 16) ?>Escribe lo que falta<?php if (!empty($result['found'])): ?><small>Leído del PDF: <?= h(implode(' · ', array_map(fn($field, $value) => ['document' => 'documento', 'full_name' => 'nombre', 'admission' => 'ingreso', 'attended_at' => 'fecha', 'specialty' => 'especialidad'][$field] . ' ' . $value, array_keys($result['found']), $result['found']))) ?></small><?php endif ?></p>
<div class="bulk-complete-grid">
<?php if (in_array('document', $missing, true)): ?><label class="bulk-complete-doc">Documento del paciente<span><select name="document_type" required aria-label="Tipo de documento"><?php foreach (App\ClinicalPdfReader::DOCUMENT_TYPES as $documentType): ?><option><?= $documentType ?></option><?php endforeach ?></select><input name="document_number" required inputmode="text" maxlength="24" pattern="[A-Za-z0-9.\- ]{3,24}" aria-label="Número de documento" placeholder="Número"></span></label><?php endif ?>
<?php if (in_array('full_name', $missing, true)): ?><label>Nombre completo del paciente<input name="full_name" required maxlength="160" autocomplete="off"></label><?php endif ?>
<?php if (in_array('admission', $missing, true)): ?><label>Número de ingreso<input name="admission" required maxlength="60" pattern="[A-Za-z0-9 ]{4,60}" autocomplete="off"></label><?php endif ?>
<?php if (in_array('attended_at', $missing, true)): ?><label>Fecha de atención<input type="date" name="attended_at" required max="<?= date('Y-m-d') ?>" min="1950-01-01"></label><?php endif ?>
<?php if (in_array('specialty', $missing, true)): ?><label>Especialidad<input name="specialty" required maxlength="120" list="<?= $fieldId ?>-specialties" autocomplete="off"><datalist id="<?= $fieldId ?>-specialties"><?php foreach ($specialties ?? [] as $specialtyOption): ?><option value="<?= h($specialtyOption['name']) ?>"><?php endforeach ?></datalist></label><?php endif ?>
</div>
<p class="bulk-complete-hint">Ábrelo con la vista previa y copia los datos tal como aparecen en el documento. Quedará registrado que los escribiste tú.</p>
<button class="button primary small" type="submit"><?= ui_icon('upload', 16) ?>Cargar con estos datos</button>
</form><?php endif ?><?php if (!empty($result['summary'])): $s = $result['summary']; $sent = array_column(array_filter($s['resolved'], fn($r) => $r['sent']), 'reference'); $held = array_column(array_filter($s['resolved'], fn($r) => !$r['sent']), 'reference'); ?><small><?= h($s['specialty']) ?> · Ingreso <?= h($s['admission']) ?> · <?= (int)$s['pages'] ?> <?= (int)$s['pages'] === 1 ? 'página' : 'páginas' ?></small><small><?= $s['orders'] ? 'Órdenes: ' . h(implode(', ', $s['orders'])) : 'Sin órdenes detectadas' ?></small><?php if ($sent): ?><small class="load-sent">Enviada a solicitud pendiente: <?= h(implode(', ', $sent)) ?></small><?php endif ?><?php if ($held): ?><small class="load-held">Revisar en Solicitudes: <?= h(implode(', ', $held)) ?></small><?php endif ?><?php endif ?></td></tr><?php endforeach ?>
</tbody></table></div></section><?php endif ?>
